    const r = await api('invitar', p.para === 'nueva' ? { rol: p.rol } : { persona: p.pid });
    p.res = { codigo: r.codigo, caduca: r.caduca, paquete: crearPaquete(r.codigo), para: p.para === 'nueva' ? '' : (dato('personas', p.pid) || {}).nombre };
